const icon=`<svg viewBox="0 0 110 62" aria-hidden="true"><path fill="currentColor" d="M2 57 35 8Q44-4 53 9L83 54Q74 65 65 52L39 16 15 54Q10 59 2 57M65 29 76 15Q82 8 88 18L109 51Q111 61 101 60L80 28 75 36Z"/></svg>`;
const motif=(style='')=>`<span class="atlas-motif ${style}" aria-hidden="true">${icon}</span>`;
const ribbon=()=>`<div class="atlas-ribbon" aria-hidden="true"><div class="atlas-ribbon-track">${Array.from({length:24},(_,i)=>motif('tone-'+i%4)).join('')}</div></div>`;
const signature=()=>`<div class="atlas-signature" aria-hidden="true">${[0,1,2].map(i=>motif('tone-'+i)).join('')}</div>`;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const products=[{id:'moroccan-corner',name:'The Moroccan Corner',category:'A ritual, beautifully gathered',price:890,image:'tea.webp',description:'Make room for an unhurried moment. A considered collection of tea objects, warm textures and carved wood, bringing the intimacy of Moroccan hospitality into your home.',details:'The Essential brings together a teapot, tray and six tea glasses. Riad adds a leather pouf and low table. Signature completes the setting with a carved folding screen.',material:'Silver-toned metal, glass, leather and walnut. Final materials and dimensions will be confirmed with the collection.',care:'Wash tea glasses by hand. Dry metal pieces after use. Dust wood with a soft cloth and protect from prolonged moisture.',variants:[['Essential',890],['Riad',1890],['Signature',2890]]},{id:'tazarine-table',name:'The Tazarine Table',category:'Sculptural wood, everyday warmth',price:1250,image:'table.webp',description:'A low, grounding silhouette with a quiet carved rhythm. Tazarine brings the warmth of walnut to a contemporary room, leaving space for the objects and rituals that make it yours.',details:'A sculptural low table with generous proportions and geometric edge detailing. Shown here as a collection concept; final dimensions will be confirmed before release.',material:'Walnut concept with a natural finish. Each piece celebrates the character of the grain.',care:'Wipe with a soft, dry cloth. Use coasters and avoid direct heat or standing water.',variants:[['Natural walnut',1250],['Dark walnut',1350]]}];
const concepts = products.slice();
if (typeof window !== 'undefined' && Array.isArray(window.ATLAS_CATALOG)) {
  products.push(...window.ATLAS_CATALOG);
}
let cart=[];try{cart=JSON.parse(sessionStorage.getItem('am-cart')||'[]').filter(x=>products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=20&&Number.isInteger(x.variant)&&products.find(p=>p.id===x.id).variants[x.variant]);}catch{}
let selected=0,quantity=1;
function persist(){try{sessionStorage.setItem('am-cart',JSON.stringify(cart));}catch{}document.querySelectorAll('[data-count]').forEach(e=>e.textContent=cart.reduce((a,x)=>a+x.qty,0));}
const total=()=>cart.reduce((a,x)=>a+products.find(p=>p.id===x.id).variants[x.variant][1]*x.qty,0);
const brand=`<a class="brand" href="/" aria-label="Atlas Muse Crafts home">${icon}<span>Atlas Muse<small>CRAFTS</small></span></a>`;
const arrow='<span aria-hidden="true">↗</span>';
function header(){return `<div class="announcement">Moroccan artifacts for modern living <span>Collection preview · USD</span></div><header>${brand}<nav aria-label="Main navigation"><a href="/collection/">The collection</a><a href="/products/moroccan-corner/">The Moroccan Corner</a><a href="/our-story/">Our story</a><a href="/policy/">Policies</a></nav><a class="bag" href="/cart/">Bag <span data-count>${cart.reduce((a,x)=>a+x.qty,0)}</span></a></header>`;}
function footer(){return `<footer><div class="footer-top"><div>${brand}<p>A little Morocco.<br>A more beautiful everyday.</p></div><div><span class="eyebrow">Explore</span><a href="/collection/">The collection</a><a href="/products/moroccan-corner/">The Moroccan Corner</a><a href="/our-story/">Our story</a><a href="/policy/">Store policies</a></div><div><span class="eyebrow">The house</span><p>Rooted in craft.<br>Considered for modern living.<br>Inspired by Morocco.</p><a href="/policy/">Policies & Care</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Atlas Muse Crafts</span><span><a href="/policy/">Store Policies</a> · Wood & copper catalog · USD. Moroccan Corner & Tazarine are collection concepts.</span></div></footer>${ribbon()}`;}
function conceptCard(p,i){return `<a class="product-card" href="/products/${p.id}/"><div class="product-image"><img src="${imageSrc(p)}" alt="${p.name}" loading="lazy"><span class="index">0${i+1}</span><span class="round-link">${arrow}</span></div><div class="product-title"><h3>${p.name}</h3><span>${p.id==='moroccan-corner'?'From ':''}${money(p.price)}</span></div><p>${p.category}</p></a>`;}
function home(){return `<section class="hero">${motif('hero-mark')}<img class="hero-photo" src="/assets/hero.webp" alt="A sunlit Moroccan living room with carved walnut furniture and warm natural textures"><div class="hero-shade"></div><div class="hero-copy"><span class="eyebrow">THE ART OF MOROCCAN LIVING</span><h1>Objects with soul.<br>Spaces with meaning.</h1><p>Craft, culture and the beauty of everyday rituals.<br>A piece of Morocco, made part of your world.</p><a class="button ivory" href="/collection/">Explore the collection ${arrow}</a></div><div class="hero-caption">ATLAS MUSE CRAFTS <span>Rooted in Morocco. At home everywhere.</span></div></section>${ribbon()}<section class="intro section">${signature()}<span class="eyebrow">A HOUSE OF CRAFT & CULTURE</span><h2>More than an object.<br>A way of living.</h2><p>The warmth of wood. The generosity of a shared table. The slow ritual of tea. We bring the spirit of Moroccan living to contemporary homes through thoughtful objects and meaningful experiences.</p><a class="text-link" href="/our-story/">Meet Atlas Muse ${arrow}</a></section><section class="section collection"><div class="section-heading"><div><span class="eyebrow">THE FIRST EDIT</span><h2>Made for your everyday.</h2></div><a class="text-link" href="/collection/">View the collection ${arrow}</a></div><div class="product-grid">${concepts.map(card).join('')}</div></section><section class="ritual"><div class="ritual-image"><img src="/assets/tea.webp" alt="Moroccan tea service, carved table and leather pouf" loading="lazy"></div><div class="ritual-copy">${motif('ritual-mark')}<span class="eyebrow">AN EXPERIENCE, BEAUTIFULLY GATHERED</span><h2>Your own<br>Moroccan corner.</h2><p>A place to pause. A reason to gather. Discover a tea ritual that brings the warmth of Moroccan hospitality home.</p><a class="button ivory" href="/products/moroccan-corner/">Discover the experience ${arrow}</a><div class="editions">ESSENTIAL <span>·</span> RIAD <span>·</span> SIGNATURE</div></div></section><section class="values section"><div><span>01 / ROOTS</span><h3>A Moroccan point of view.</h3><p>Our inspiration begins in the textures, gestures and generous spirit of Moroccan life.</p></div><div><span>02 / CRAFT</span><h3>Character in every detail.</h3><p>We value the human touch and the small variations that give crafted objects their soul.</p></div><div><span>03 / LIVING</span><h3>Beauty to live with.</h3><p>Considered forms and useful objects, designed to belong in the rhythm of your home.</p></div></section>`;}
function conceptProduct(p){return `<div class="breadcrumbs"><a href="/collection/">The collection</a><span>/</span>${p.name}</div><section class="product-detail"><div class="detail-image"><img src="${imageSrc(p)}" alt="${p.name}"><span>THE ATLAS MUSE COLLECTION</span></div><div class="detail-copy">${signature()}<span class="eyebrow">${p.id==='moroccan-corner'?'THE ART OF GATHERING':'FURNITURE / THE FIRST EDIT'}</span><h1>${p.name}</h1><p class="product-sub">${p.category}</p><p class="price" id="price">${money(p.variants[selected][1])}<small>USD · illustrative price</small></p><p>${p.description}</p><fieldset><legend>${p.id==='moroccan-corner'?'Choose your experience':'Choose your finish'}</legend><div class="variants">${p.variants.map((v,i)=>`<button class="variant ${selected===i?'selected':''}" data-variant="${i}" aria-pressed="${selected===i}">${v[0]}</button>`).join('')}</div></fieldset><div id="variant-description" class="muted">${variantText(p)}</div><div class="buy-row"><div class="quantity"><button data-minus aria-label="Decrease quantity">−</button><span id="quantity">${quantity}</span><button data-plus aria-label="Increase quantity">+</button></div><button class="button primary" data-add="${p.id}">Add to bag <span>+</span></button></div><div role="status" id="add-status" class="add-status"></div><p class="muted small">Collection preview. Delivery options and final specifications will be confirmed before orders open.</p><div class="accordions"><details open><summary>The details</summary><p>${p.details}</p></details><details><summary>Materials & character</summary><p>${p.material}</p></details><details><summary>Care for your piece</summary><p>${p.care}</p></details></div></div></section><section class="section related"><div class="section-heading"><h2>In good company.</h2><a class="text-link" href="/collection/">All pieces ${arrow}</a></div><div class="product-grid">${concepts.filter(x=>x.id!==p.id).map(card).join('')}</div></section>`;}
function variantText(p){return p.id==='moroccan-corner'?['Teapot, tray & six tea glasses.','The tea service, a leather pouf & low table.','The full Riad experience, plus a carved folding screen.'][selected]:['Warm, natural wood character.','A deeper, richer walnut tone.'][selected];}
function cartRows(compact=false){return cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);if(!p)return '';const vName=(p.variants&&p.variants[x.variant]&&p.variants[x.variant][0])||'Standard';const vPrice=(p.variants&&p.variants[x.variant]&&p.variants[x.variant][1])||p.price||0;return `<div class="cart-item"><a href="/products/${p.id}/"><img src="${imageSrc(p)}" alt="${p.name}"></a><div><h3><a href="/products/${p.id}/">${p.name}</a></h3><p>${vName}</p>${compact?`<p>Quantity: ${x.qty}</p>`:`<div class="quantity"><button data-cart-minus="${i}" aria-label="Decrease ${p.name} quantity">−</button><span>${x.qty}</span><button data-cart-plus="${i}" aria-label="Increase ${p.name} quantity">+</button></div><button class="remove" data-remove="${i}">Remove</button>`}</div><strong>${money(vPrice*x.qty)}</strong></div>`;}).join('');}
function getShopifyCheckoutUrl(){const lines=[];for(const it of cart){const p=products.find(x=>x.id===it.id);if(p?.imported&&p.variantData&&p.variantData[it.variant]){const v=p.variantData[it.variant];const vid=v.id||p.sourceId;if(vid)lines.push(`${vid}:${it.qty}`);}}if(!lines.length)return null;return `https://atlasmusecrafts.com/cart/${lines.join(',')}`;}
function summary(checkout=false){const shopifyUrl=getShopifyCheckoutUrl();return `<aside class="order-summary">${signature()}<span class="eyebrow">YOUR SELECTION</span><h2>Order summary</h2>${checkout?cartRows(true):''}<div class="summary-line"><span>Subtotal</span><span>${money(total())}</span></div><div class="summary-line"><span>Delivery</span><span>To be confirmed</span></div><div class="summary-line"><span>Taxes & duties</span><span>To be confirmed</span></div><div class="summary-total"><span>Estimated subtotal</span><strong>${money(total())}</strong></div>${checkout?'':`<a class="button primary" href="/checkout/">Continue to checkout ${arrow}</a>`}${shopifyUrl?`<div class="shopify-checkout-card"><span class="eyebrow">OFFICIAL STORE CHECKOUT</span><h3>Complete on AtlasMuseCrafts.com</h3><p>Order these handcrafted pieces directly through our live Shopify store with insured international delivery.</p><a class="shopify-btn" href="${shopifyUrl}" target="_blank" rel="noopener">Proceed to Shopify Checkout ${arrow}</a></div>`:''}<p class="small muted" style="margin-top:16px">Imported items show live catalog prices in USD. Concept pieces (Moroccan Corner & Tazarine) are preview editions.</p></aside>`;}
function empty(){return `<section class="empty"><span class="eyebrow">ROOM FOR SOMETHING BEAUTIFUL</span><h1>Your bag is empty.</h1><p>Find a piece that feels like home.</p><a class="button primary" href="/collection/">Explore the collection ${arrow}</a></section>`;}
function bag(){return cart.length?`<section class="page-intro compact"><span class="eyebrow">YOUR ATLAS MUSE SELECTION</span><h1>The shopping bag.</h1></section><section class="cart-layout section"><div>${cartRows()}<a class="text-link" href="/collection/">← Continue exploring</a></div>${summary()}</section>`:empty();}
function checkout(){return cart.length?`<section class="page-intro compact"><span class="eyebrow">ONE STEP CLOSER TO HOME</span><h1>Checkout.</h1><p>Preview checkout — no payment will be collected and no order will be placed.</p></section><section class="checkout-layout section"><form id="checkout-form"><div class="form-section"><h2><span>01</span> Contact</h2><label>Email address<input type="email" name="email" autocomplete="email" placeholder="you@example.com" required></label></div><div class="form-section"><h2><span>02</span> Delivery details</h2><div class="form-grid"><label>First name<input name="firstName" autocomplete="given-name" required maxlength="80"></label><label>Last name<input name="lastName" autocomplete="family-name" required maxlength="80"></label><label class="full">Address<input name="address" autocomplete="street-address" required maxlength="200"></label><label>City<input name="city" autocomplete="address-level2" required maxlength="100"></label><label>Postal code<input name="postal" autocomplete="postal-code" required maxlength="30"></label><label class="full">Country<select name="country" autocomplete="country-name" required><option value="">Select your country</option><option>United States</option><option>Canada</option><option>France</option><option>United Kingdom</option><option>Germany</option><option>Morocco</option><option>Other</option></select></label></div><p class="muted small">Details stay on this page and are not sent or saved. Delivery availability is not yet confirmed.</p></div><div class="form-section"><h2><span>03</span> Payment</h2><div class="payment-preview">Payment will become available when the store opens. No card details are needed for this preview.</div></div><button class="button primary full-button" type="submit">Preview order ${arrow}</button><a class="back" href="/cart/">← Return to bag</a></form>${summary(true)}</section>`:empty();}
function story(){return `<section class="story"><div class="story-copy">${signature()}<span class="eyebrow">THE ATLAS MUSE PHILOSOPHY</span><h1>Rooted in Morocco.<br>Made for living.</h1><p>We believe that a home is shaped by the things we choose to live with — and the moments we make around them.</p><p>Atlas Muse Crafts brings a Moroccan perspective to contemporary living. Our world is one of carved wood, generous tables, warm textures and the quiet ceremony of tea.</p><p>Our mission is to bring Moroccan craftsmanship into modern homes. Our vision is to share the art of Moroccan living worldwide, with authenticity, care and a lasting appreciation for craft.</p><a class="button primary" href="/collection/">Discover our world ${arrow}</a></div><img src="/assets/hero.webp" alt="Warm contemporary room inspired by Moroccan living"></section><section class="statement">${motif('statement-mark')}<span class="eyebrow">OUR BELIEF</span><h2>The most beautiful things<br>bring us closer.</h2></section>`;}
function policy(){return `<section class="page-intro">${motif('page-mark')}<span class="eyebrow">TRANSPARENCY & CRAFT</span><h1>Store policies.</h1><p>Our commitment to authentic craftsmanship, clear expectations, and thoughtful service for every Atlas Muse client.</p></section><section class="section policy-page"><div class="breadcrumbs"><a href="/">The house</a><span>/</span>Store policies</div><div class="policy-meta-bar"><span><strong>Effective Date:</strong> 22 September 2026</span><span><strong>Last Updated:</strong> 22 September 2026</span><span><strong>Orders:</strong> Global online orders · USD</span></div><div class="policy-summary-card"><span class="eyebrow">QUICK REFERENCE</span><h2>Website policy summary</h2><p class="summary-intro">This summary provides a fast overview of key terms on product and checkout pages. The complete Store Policies below control all purchases.</p><div class="policy-summary-grid"><div class="policy-summary-item"><strong>Ready-to-Ship Processing</strong>Usually processed and dispatched within 3–7 business days.</div><div class="policy-summary-item"><strong>Made-to-Order Timelines</strong>Generally require 4–12 weeks before dispatch; applicable estimate is shown on product pages.</div><div class="policy-summary-item"><strong>International Transit</strong>Begins after dispatch (excluding customs clearance): Morocco (2–7 d), Europe (5–15 d), US & Canada (7–20 d).</div><div class="policy-summary-item"><strong>Customs & Import Duties</strong>Shipments are sent duties unpaid (DDU/DAP) unless expressly stated. Customers are the importer of record.</div><div class="policy-summary-item"><strong>14-Day Return Window</strong>Eligible unused ready-made pieces can be returned within 14 calendar days of delivery with prior authorization.</div><div class="policy-summary-item"><strong>Custom Pieces Excluded</strong>Personalized, customized, and made-to-order items are non-returnable once design or production has begun.</div><div class="policy-summary-item"><strong>Damage Inspection (48h)</strong>Inspect outer packaging at delivery; photograph damage, retain packaging, and notify us within 48 hours.</div><div class="policy-summary-item"><strong>12-Month Warranty</strong>Atlas Muse Crafts warrants products for 12 months from delivery against material defects in workmanship.</div><div class="policy-summary-item"><strong>Handmade Variations</strong>Natural differences in grain, carving, color, glaze, and dimensions are authentic character traits, not defects.</div></div></div><div class="policy-layout"><nav class="policy-toc" aria-label="Table of contents"><h3>Table of Contents</h3><ul class="policy-toc-list"><li><a class="policy-toc-link" href="#sec-1">1. Products & Craftsmanship</a></li><li><a class="policy-toc-link" href="#sec-2">2. Orders & Acceptance</a></li><li><a class="policy-toc-link" href="#sec-3">3. Payment Policy</a></li><li><a class="policy-toc-link" href="#sec-4">4. Production & Processing</a></li><li><a class="policy-toc-link" href="#sec-5">5. Shipping & Delivery</a></li><li><a class="policy-toc-link" href="#sec-6">6. Customs & Import Taxes</a></li><li><a class="policy-toc-link" href="#sec-7">7. Cancellations</a></li><li><a class="policy-toc-link" href="#sec-8">8. Returns & Exchanges</a></li><li><a class="policy-toc-link" href="#sec-9">9. Damage, Defects & Claims</a></li><li><a class="policy-toc-link" href="#sec-10">10. Refunds</a></li><li><a class="policy-toc-link" href="#sec-11">11. Warranty & Product Care</a></li><li><a class="policy-toc-link" href="#sec-12">12. Trade & Project Orders</a></li><li><a class="policy-toc-link" href="#sec-13">13. Force Majeure</a></li><li><a class="policy-toc-link" href="#sec-14">14. Fraud & Resale</a></li><li><a class="policy-toc-link" href="#sec-15">15. Privacy</a></li><li><a class="policy-toc-link" href="#sec-16">16. Governing Terms & Rights</a></li><li><a class="policy-toc-link" href="#sec-17">17. Changes to Policies</a></li><li><a class="policy-toc-link" href="#sec-18">18. Contact Us</a></li></ul></nav><div class="policy-content"><section id="sec-1" class="policy-section"><span class="policy-section-num">SECTION 01</span><h2>1. Products and Craftsmanship</h2><p>These Store Policies apply to purchases made through the Atlas Muse Crafts website (the “Website”). By placing an order, you agree to these policies, together with our Terms and Conditions and Privacy Policy.</p><p>Atlas Muse Crafts offers handcrafted Moroccan furniture, decorative objects, architectural pieces, home accessories, and curated lifestyle collections. Because many pieces are handmade, natural variations and longer production times are part of their character. Nothing in these policies limits any mandatory consumer right available under the law applicable to you.</p><h3>1.1 Handmade character</h3><p>Our products are made or finished by craftspeople using traditional materials and techniques. Small differences in color, grain, texture, carving, glaze, pattern, dimensions, and finish are normal and make each piece unique. These natural variations are not defects.</p><h3>1.2 Product information</h3><p>We make reasonable efforts to display product descriptions, measurements, materials, colors, and photographs accurately. Screen settings, lighting, handmade production, and natural materials may cause the delivered item to differ slightly from its online appearance.</p><p>Customers are responsible for reviewing all dimensions, materials, care instructions, lead times, and installation requirements before ordering. For furniture or architectural pieces, customers should measure doors, corridors, staircases, elevators, and the intended installation area.</p><h3>1.3 Availability</h3><p>Products may be:</p><ul><li><strong>Ready to ship:</strong> currently in stock and generally dispatched after order processing.</li><li><strong>Made to order:</strong> produced after the order is confirmed.</li><li><strong>Customized or personalized:</strong> made according to specifications approved by the customer.</li><li><strong>Limited edition or one of a kind:</strong> available in limited quantities and not guaranteed to be restocked.</li></ul><p>Adding an item to a cart does not reserve it. If an item becomes unavailable after payment, we will offer a replacement, store credit, a revised delivery estimate, or a full refund.</p><h3>1.4 Prices</h3><p>Prices are shown in the currency selected or displayed on the Website. Unless expressly stated otherwise, prices exclude import duties, customs charges, local taxes, brokerage fees, installation, and special delivery services. Shipping charges and any taxes collected by us are shown before payment.</p><p>We may correct pricing or product-information errors before dispatch. If a correction materially affects an accepted order, we will contact the customer for approval or cancel and refund the affected item.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-2" class="policy-section"><span class="policy-section-num">SECTION 02</span><h2>2. Orders and Acceptance</h2><h3>2.1 Placing an order</h3><p>An order is submitted when the customer completes checkout. The automatic order-confirmation email acknowledges receipt but does not necessarily constitute final acceptance. The order is accepted when Atlas Muse Crafts confirms it, begins production, or dispatches the product, whichever occurs first.</p><h3>2.2 Order review</h3><p>We may contact the customer to verify identity, payment information, delivery information, product specifications, or intended use. We may refuse or cancel an order for suspected fraud, payment failure, pricing error, stock unavailability, delivery restrictions, sanctions or legal restrictions, or inability to produce the requested item safely or accurately.</p><p>If Atlas Muse Crafts cancels an order after payment, the amount collected for the cancelled item will be refunded to the original payment method.</p><h3>2.3 Customer information</h3><p>The customer must provide a complete and accurate name, email address, telephone number, billing address, delivery address, and any information reasonably required for delivery or customs clearance. Costs resulting from incorrect, incomplete, or outdated information may be charged to the customer.</p><h3>2.4 Changes to an order</h3><p>Requests to change a delivery address, finish, size, quantity, or other specification must be submitted promptly. A change is valid only after written confirmation from Atlas Muse Crafts. Changes may affect the price and delivery date. Once production, packing, or dispatch has begun, a change may not be possible.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-3" class="policy-section"><span class="policy-section-num">SECTION 03</span><h2>3. Payment Policy</h2><h3>3.1 Accepted methods</h3><p>We accept the payment methods displayed at checkout, which may include major credit or debit cards, digital wallets, and other approved payment services. Availability depends on the customer’s country and the payment provider.</p><h3>3.2 Payment authorization</h3><p>Full payment is generally required when an order is placed. Atlas Muse Crafts may offer a deposit or installment arrangement for selected custom, trade, hospitality, or high-value orders. Any such arrangement must be confirmed in writing.</p><p>Unless otherwise agreed in writing, a deposit for customized or made-to-order work becomes non-refundable once design, material procurement, or production begins, except where cancellation or refund rights are required by law or Atlas Muse Crafts cannot fulfil the order.</p><h3>3.3 Currency conversion and bank fees</h3><p>If the customer’s payment account uses a different currency from the checkout currency, the card issuer or payment provider determines the conversion rate and may charge foreign-exchange or international transaction fees. Atlas Muse Crafts does not control and is not responsible for those charges.</p><h3>3.4 Payment security</h3><p>Payments are processed through third-party payment providers using their secure systems. Atlas Muse Crafts does not intentionally store complete payment-card numbers. Payment processing is also subject to the provider’s terms and privacy practices.</p><h3>3.5 Failed, reversed, or disputed payments</h3><p>An order will not be produced or dispatched until required payment is successfully received. If a payment is reversed, charged back, or disputed without valid grounds, Atlas Muse Crafts may suspend fulfilment, cancel the order, recover reasonable costs, and restrict future purchases. Customers should contact us first so that we can investigate and resolve any issue.</p><h3>3.6 Promotions and discount codes</h3><p>Promotional codes must be used before checkout, cannot be exchanged for cash, and cannot be applied retroactively unless stated otherwise. Only one code may be used per order unless the promotion expressly allows combinations. Discounts may exclude custom work, limited editions, shipping, taxes, or selected collections.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-4" class="policy-section"><span class="policy-section-num">SECTION 04</span><h2>4. Production and Processing Times</h2><h3>4.1 Ready-to-ship items</h3><p>Ready-to-ship items are normally processed within <strong>3–7 business days</strong>, excluding weekends and public holidays. Quality checks, export documentation, oversized packing, or seasonal demand may extend this period.</p><h3>4.2 Made-to-order items</h3><p>The estimated production period for made-to-order products is stated on the product page or order quotation. Unless a different period is shown, customers should allow approximately <strong>4–12 weeks</strong> before dispatch. Complex furniture, architectural pieces, large-volume orders, and customized projects may require more time.</p><h3>4.3 Estimates, not guarantees</h3><p>Production and delivery dates are good-faith estimates, not guaranteed dates, unless Atlas Muse Crafts expressly agrees in writing to a guaranteed deadline. Handmade production, material availability, artisan schedules, weather, customs, carrier disruptions, and events outside our reasonable control can cause delays.</p><p>If a material delay occurs, we will provide an updated estimate and the options available under applicable law.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-5" class="policy-section"><span class="policy-section-num">SECTION 05</span><h2>5. Shipping and Delivery Policy</h2><h3>5.1 Destinations</h3><p>We primarily ship to the United States, Canada, Europe, Morocco, and other destinations supported at checkout or approved by quotation. Certain oversized, fragile, restricted, or location-specific products may not be available for every destination.</p><h3>5.2 Shipping charges</h3><p>Shipping charges are calculated at checkout or provided by quotation based on the product, weight, dimensions, destination, service level, and required handling. For remote locations, oversized products, white-glove delivery, or orders requiring special customs arrangements, an additional charge may be necessary. We will seek approval before collecting a material additional amount.</p><h3>5.3 Estimated transit times</h3><p>Transit begins only after production, quality control, and dispatch. Typical transit estimates are:</p><div class="policy-table-wrapper"><table class="policy-table"><thead><tr><th>Destination</th><th>Estimated Transit (After Dispatch)</th><th>Delivery Notes</th></tr></thead><tbody><tr><td><strong>Morocco</strong></td><td>2–7 business days</td><td>Direct domestic courier or artisan transport</td></tr><tr><td><strong>Europe (EU & UK)</strong></td><td>5–15 business days</td><td>Air freight or expedited overland courier</td></tr><tr><td><strong>United States & Canada</strong></td><td>7–20 business days</td><td>Air freight or maritime container freight</td></tr><tr><td><strong>Other International</strong></td><td>Provided at checkout / quotation</td><td>Subject to destination customs processing</td></tr></tbody></table></div><p class="small muted">These periods exclude production lead time, export/customs inspections, remote-area delivery routing, and delays outside our control.</p><h3>5.4 Tracking</h3><p>Where tracking is available, the customer will receive tracking information after dispatch. Tracking may take time to update. Large freight shipments may be coordinated directly by the carrier.</p><h3>5.5 Delivery methods</h3><p>Standard parcel delivery generally means delivery to the address or building entrance and does not include unpacking, assembly, installation, or removal of packaging. Curbside freight delivery may require the customer to move the item indoors. White-glove delivery or installation is included only if expressly purchased or confirmed in writing.</p><h3>5.6 Inspection at delivery</h3><p>The customer or an authorized person should inspect the outer packaging before accepting delivery. If damage is visible, the customer should:</p><ol><li>Note the damage on the carrier’s delivery record before signing;</li><li>Photograph the package and item from several angles;</li><li>Retain all packaging, protective wrapping, and labels; and</li><li>Notify Atlas Muse Crafts within <strong>48 hours</strong> of delivery.</li></ol><p>Signing a delivery record as “received in good condition” may make a carrier claim more difficult, but it does not remove any mandatory legal rights.</p><h3>5.7 Missed or refused delivery</h3><p>The customer is responsible for being available at the agreed delivery location. Re-delivery, storage, address-correction, return-to-sender, or handling charges resulting from an unavailable recipient, refusal without valid cause, or incorrect address may be charged to the customer.</p><h3>5.8 Transfer of risk</h3><p>Risk of accidental loss or damage passes as provided by the mandatory law applicable to the order. Where no mandatory rule applies, risk passes upon delivery to the customer or a person designated by the customer. If the customer independently appoints a carrier not offered by Atlas Muse Crafts, risk may pass when the product is handed to that carrier.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-6" class="policy-section"><span class="policy-section-num">SECTION 06</span><h2>6. Customs, Duties, and Import Taxes</h2><p>International orders may be subject to import duties, VAT/GST, customs charges, brokerage fees, inspection fees, or other local assessments.</p><p>Unless checkout or the quotation expressly states that delivery is <strong>duties paid</strong>, the shipment is sent <strong>duties unpaid</strong>, and the customer is the importer of record responsible for all destination-country charges, documentation, and compliance requirements.</p><p>Customs authorities may request identification, tax numbers, proof of purchase, or other documents. Delays caused by customs are outside Atlas Muse Crafts’ direct control. If the customer refuses to pay required import charges and the shipment is returned, we may deduct unrecoverable shipping, customs, storage, brokerage, and return costs from any refund, to the extent permitted by law.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-7" class="policy-section"><span class="policy-section-num">SECTION 07</span><h2>7. Cancellations</h2><h3>7.1 Ready-to-ship orders</h3><p>A ready-to-ship order may be cancelled for a full refund if the request is received before packing or dispatch. Once dispatched, the return rules below apply.</p><h3>7.2 Made-to-order and customized orders</h3><p>Customers should request cancellation as soon as possible. If design work, material procurement, or production has begun, the order may be non-cancellable or subject to deductions reflecting work completed, committed materials, payment-processing costs, and other irrecoverable expenses, except where applicable law provides otherwise.</p><h3>7.3 Legal cancellation rights</h3><p>Where a mandatory cooling-off or withdrawal right applies, Atlas Muse Crafts will honor it. Such rights may not apply, or may apply differently, to products made to the customer’s specifications, clearly personalized products, or certain sealed or hygiene-sensitive products.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-8" class="policy-section"><span class="policy-section-num">SECTION 08</span><h2>8. Returns and Exchanges</h2><h3>8.1 Eligible ready-made items</h3><p>Subject to the exclusions below, a customer may request a return of an unused ready-made item within <strong>14 calendar days after delivery</strong>. The item must be returned in its original condition, with all accessories, documentation, protective materials, and original packaging.</p><p>The customer must contact Atlas Muse Crafts and receive return instructions before shipping an item back. Unauthorized returns may be refused.</p><h3>8.2 Non-returnable items</h3><p>Except where defective, damaged, incorrectly supplied, or returnable by mandatory law, the following are not eligible for change-of-mind returns:</p><ul><li>Customized, personalized, monogrammed, or made-to-measure products;</li><li>Made-to-order products for which production has begun;</li><li>One-of-a-kind pieces specifically reserved or sourced for the customer;</li><li>Installed, assembled, altered, repaired, used, washed, stained, or damaged items;</li><li>Clearance or final-sale items identified as such before purchase;</li><li>Gift cards;</li><li>Products returned without required parts, packaging, or authorization; and</li><li>Items that cannot be returned for health, hygiene, or safety reasons after opening, where permitted by law.</li></ul><h3>8.3 Return shipping</h3><p>For change-of-mind returns, the customer is responsible for return shipping, insurance, customs clearance, duties, and safe packaging, unless applicable law requires otherwise. Original outbound shipping and optional service charges are not refundable except where required by law.</p><p>The customer bears the risk of the return until it reaches the designated return location. We strongly recommend a tracked, insured service. Oversized products may require an approved freight carrier.</p><h3>8.4 Return condition</h3><p>Returned products are inspected on arrival. If handling beyond what is reasonably necessary to examine the product has reduced its value, Atlas Muse Crafts may make a lawful deduction from the refund. We may reject products that are materially damaged, incomplete, or inconsistent with the authorized return, without affecting mandatory consumer protections.</p><h3>8.5 Exchanges</h3><p>Exchanges depend on availability. The fastest option may be to return the eligible product and place a new order. Any difference in price, shipping, tax, duty, or other charges is payable by the customer.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-9" class="policy-section"><span class="policy-section-num">SECTION 09</span><h2>9. Damaged, Defective, Missing, or Incorrect Items</h2><p>Customers should notify Atlas Muse Crafts of visible transit damage within <strong>48 hours</strong> and of a missing, defective, or incorrect product as soon as reasonably possible. A delay in reporting does not cancel mandatory rights, but prompt notice helps us preserve evidence and make a carrier claim.</p><p>The claim should include:</p><ul><li>The order number;</li><li>A clear description of the issue;</li><li>Photographs or video of the item, packaging, shipping label, and damage;</li><li>Photographs showing the entire item and close-up details; and</li><li>Confirmation that the original packaging has been retained.</li></ul><p>After assessment, we may arrange repair, replacement, supply of missing parts, a partial refund, or a full refund, as appropriate and subject to applicable law. Do not discard, repair, install, or return an affected item before receiving instructions unless necessary to prevent further harm.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-10" class="policy-section"><span class="policy-section-num">SECTION 10</span><h2>10. Refunds</h2><h3>10.1 Approval and timing</h3><p>Once an eligible return or claim is received and inspected, we will notify the customer of the outcome. Approved refunds are issued to the original payment method, normally within <strong>10 business days</strong> after approval. The bank or payment provider may require additional time to display the credit.</p><h3>10.2 Refund amount</h3><p>Refunds include the amounts required by applicable law. Depending on the reason for return, lawful deductions may include non-refundable delivery upgrades, return shipping, duties, customs, storage, damage, missing components, diminished value, or irrecoverable custom-production costs.</p><h3>10.3 Partial refunds</h3><p>When a customer chooses to keep an item with a minor issue, Atlas Muse Crafts may offer a mutually agreed partial refund or repair contribution as a final resolution of that specific issue.</p><h3>10.4 Gift cards and store credit</h3><p>Gift cards and store credit are not redeemable for cash, except where required by law. Refunds for orders paid partly by gift card or store credit may be returned first to that original form of payment.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-11" class="policy-section"><span class="policy-section-num">SECTION 11</span><h2>11. Warranty and Product Care</h2><h3>11.1 Limited workmanship warranty</h3><p>In addition to mandatory legal guarantees, Atlas Muse Crafts warrants for <strong>12 months from delivery</strong> that products will be free from material defects in workmanship under normal residential use. If a valid claim is confirmed, our remedy may be repair, replacement, replacement parts, or refund, depending on the circumstances and applicable law.</p><h3>11.2 Exclusions</h3><p>The limited warranty does not cover:</p><ul><li>Natural variation, patina, wood movement, minor glaze variation, or other inherent characteristics of handmade and natural materials;</li><li>Normal wear and tear;</li><li>Fading, discoloration, cracking, warping, corrosion, or damage caused by sunlight, humidity, dryness, heat, water, chemicals, pests, or unsuitable environmental conditions;</li><li>Misuse, accident, negligence, improper cleaning, improper storage, commercial use, or failure to follow care instructions;</li><li>Incorrect assembly or installation not performed or approved by Atlas Muse Crafts;</li><li>Modifications or repairs by an unauthorized party; or</li><li>Damage occurring after delivery while the item is moved or transported by the customer.</li></ul><h3>11.3 Care responsibility</h3><p>Customers should follow the care instructions supplied with the product or published on the Website. Indoor products should not be used outdoors unless expressly described as suitable for outdoor use. Furniture and architectural items must be installed using appropriate professional expertise and suitable fixings for the relevant wall, floor, or structure.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-12" class="policy-section"><span class="policy-section-num">SECTION 12</span><h2>12. Trade, Hospitality, and Project Orders</h2><p>Trade, interior-design, architectural, wholesale, and hospitality orders may be governed by a separate quotation or contract addressing samples, approvals, tolerances, project milestones, deposits, production schedules, delivery, installation, storage, cancellation, and warranty. If a signed quotation or project agreement conflicts with these Store Policies, the signed agreement controls for that order, subject to mandatory law.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-13" class="policy-section"><span class="policy-section-num">SECTION 13</span><h2>13. Force Majeure and Delivery Delays</h2><p>Atlas Muse Crafts is not liable for delay or failure caused by events beyond its reasonable control, including natural disasters, severe weather, fire, epidemic, war, civil unrest, government action, border closure, sanctions, strikes, transport interruption, customs delay, port congestion, carrier failure, power or network outage, raw-material shortage, or artisan incapacity.</p><p>We will take reasonable steps to reduce the effect of such an event, communicate material delays, and provide any remedy required by law.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-14" class="policy-section"><span class="policy-section-num">SECTION 14</span><h2>14. Fraud Prevention and Resale</h2><p>We may use reasonable fraud-prevention measures and request additional verification before accepting or dispatching an order. Products may not be purchased for unlawful export, counterfeit resale, or any prohibited commercial purpose. Wholesale or authorized resale arrangements require prior written approval.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-15" class="policy-section"><span class="policy-section-num">SECTION 15</span><h2>15. Privacy</h2><p>We process customer information to accept payments, fulfil orders, arrange delivery, provide support, prevent fraud, and comply with legal obligations. For more information about personal data, cookies, international transfers, and customer rights, please review the Atlas Muse Crafts Privacy Policy.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-16" class="policy-section"><span class="policy-section-num">SECTION 16</span><h2>16. Governing Terms and Consumer Rights</h2><p>These policies are intended to be read with the Atlas Muse Crafts Terms and Conditions. Any governing-law and dispute-resolution provisions appear in those Terms.</p><p>Nothing in these policies excludes or limits liability or consumer rights that cannot lawfully be excluded or limited. If any part of these policies conflicts with mandatory law in the customer’s country, the mandatory law prevails and the remainder continues to apply.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-17" class="policy-section"><span class="policy-section-num">SECTION 17</span><h2>17. Changes to These Policies</h2><p>We may update these policies to reflect changes to our products, delivery services, payment arrangements, business practices, or legal obligations. The version in effect when an order is placed generally governs that order, except where a change is required by law or is more favorable to the customer.</p><a class="policy-back-to-top" href="#main">↑ Back to top</a></section><section id="sec-18" class="policy-section"><span class="policy-section-num">SECTION 18</span><h2>18. Contact Us</h2><p>For order changes, cancellations, returns, delivery questions, or product claims, contact our concierge:</p><div class="policy-contact-card"><h4>Atlas Muse Crafts Concierge</h4><p><strong>Website:</strong> <a href="https://atlasmusecrafts.com/" target="_blank" rel="noopener">https://atlasmusecrafts.com/</a></p><p><strong>Email:</strong> <a href="mailto:concierge@atlasmusecrafts.com">concierge@atlasmusecrafts.com</a></p><p><strong>Client Relations:</strong> Marrakech & London</p><p><strong>Return Address:</strong> Provided individually upon return authorization</p><p class="small muted" style="margin-top:14px;color:var(--wine)">Please include your order number in all correspondence. Do not dispatch returns to business offices without prior written return authorization.</p></div><a class="policy-back-to-top" href="#main">↑ Back to top</a></section></div></div></section>`;}
function render(){selected=0;quantity=1;const rawPath=location.pathname.replace(/\/+$/,'')||'/';let html,title='Atlas Muse Crafts — Moroccan Artifacts for Modern Living';if(rawPath==='/'||rawPath==='')html=home();else if(rawPath==='/collection'||rawPath==='/products'){html=collection();title='The Collection — Atlas Muse Crafts';}else if(rawPath==='/cart'){html=bag();title='Shopping Bag — Atlas Muse Crafts';}else if(rawPath==='/checkout'){html=checkout();title='Checkout — Atlas Muse Crafts';}else if(rawPath==='/our-story'){html=story();title='Our Story — Atlas Muse Crafts';}else if(rawPath==='/policy'||rawPath==='/policies'){html=policy();title='Store Policies — Atlas Muse Crafts';}else if(rawPath.startsWith('/products/')){const slug=rawPath.replace(/^\/products\//,'').replace(/\/+$/,'');const p=products.find(x=>x.id===slug||rawPath==='/products/'+x.id);if(p){html=product(p);title=p.name+' — Atlas Muse Crafts';}else{html=`<section class="empty"><span class="eyebrow">PIECE NOT FOUND</span><h1>This piece has wandered.</h1><p>The handcrafted item you are searching for may have been archived or is resting in our Marrakech workshop.</p><a class="button primary" href="/collection/">Explore the collection ${arrow}</a></section>`;title='Piece Not Found — Atlas Muse Crafts';}}else{html=`<section class="empty"><span class="eyebrow">PAGE NOT FOUND</span><h1>This page has wandered.</h1><p>The path you took does not lead to an Atlas Muse room.</p><a class="button primary" href="/">Back to the house ${arrow}</a></section>`;title='Page Not Found — Atlas Muse Crafts';}document.title=title;const appEl=document.getElementById('app');if(appEl){appEl.innerHTML=header()+`<main id="main">${html}</main>`+footer();}wire();}
function add(id,variant,qty){const p=products.find(p=>p.id===id);if(p?.imported && p.variantData && !p.variantData[variant]?.available)throw Error('This option is sold out');if(!p||!Number.isInteger(variant)||!Number.isInteger(qty)||qty<1||qty>20)throw Error('Invalid selection');let existing=cart.find(x=>x.id===id&&x.variant===variant);if(existing)existing.qty=Math.min(20,existing.qty+qty);else cart.push({id,variant,qty});persist();return {items:cart,total:total()};}
function wire(){wireCatalog();document.querySelectorAll('.policy-toc-link').forEach(link=>{link.onclick=e=>{e.preventDefault();const id=link.getAttribute('href');const el=document.querySelector(id);if(el)el.scrollIntoView({behavior:'smooth'});};});document.querySelectorAll('[data-variant]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.variant);const rawPath=location.pathname.replace(/\/+$/,'')||'/';const p=products.find(p=>rawPath.includes(p.id));if(!p)return;document.querySelectorAll('[data-variant]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});const priceEl=document.getElementById('price');if(priceEl&&p.variants&&p.variants[selected])priceEl.innerHTML=money(p.variants[selected][1])+'<small>USD · illustrative price</small>';const descEl=document.getElementById('variant-description');if(descEl)descEl.textContent=variantText(p);});const minus=document.querySelector('[data-minus]'),plus=document.querySelector('[data-plus]');if(minus)minus.onclick=()=>{quantity=Math.max(1,quantity-1);const q=document.getElementById('quantity');if(q)q.textContent=quantity;};if(plus)plus.onclick=()=>{quantity=Math.min(20,quantity+1);const q=document.getElementById('quantity');if(q)q.textContent=quantity;};const a=document.querySelector('[data-add]');if(a)a.onclick=()=>{try{add(a.dataset.add,selected,quantity);const s=document.getElementById('add-status');if(s)s.innerHTML='Added to your bag. <a href="/cart/">View bag →</a>';}catch(err){const s=document.getElementById('add-status');if(s)s.textContent=err.message||'Could not add to bag';}};for(const action of ['minus','plus'])document.querySelectorAll('[data-cart-'+action+']').forEach(b=>b.onclick=()=>{const i=Number(b.getAttribute('data-cart-'+action));if(cart[i]){cart[i].qty=Math.max(1,Math.min(20,cart[i].qty+(action==='plus'?1:-1)));persist();render();}});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);persist();render();});const form=document.getElementById('checkout-form');if(form)form.onsubmit=e=>{e.preventDefault();const main=document.getElementById('main');if(main)main.innerHTML=`<section class="empty review"><span class="eyebrow">YOUR ORDER PREVIEW</span><h1>A beautiful selection.</h1><p>Your checkout preview is complete. No order has been placed, no payment collected, and no personal details saved.</p><div class="review-items">${cartRows(true)}<div class="summary-total"><span>Illustrative subtotal</span><strong>${money(total())}</strong></div></div><a class="button primary" href="/collection/">Continue exploring ${arrow}</a></section>`;window.scrollTo(0,0);};}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const imageSrc=p=>p.imported?p.image:'/assets/'+p.image;
const sized=(url,width=800)=>url?(url+(url.includes('?')?'&':'?')+'width='+width):'';
function card(p,i){if(!p.imported)return conceptCard(p,i);const variants=p.variantData||[];const v=variants.find(v=>v.price===p.price)||variants[0]||{price:p.price,compare:0,available:true};const varies=variants.some(v=>v.price!==p.price);const isAvail=variants.length?variants.some(v=>v.available):true;const isSale=(v.compare||0)>(v.price||p.price);const mainImg=p.image||(p.images&&p.images[0]&&p.images[0].src)||'/assets/hero.webp';const altText=(p.images&&p.images[0]&&p.images[0].alt)||p.name;return `<a class="product-card" href="/products/${p.id}/"><div class="product-image"><img src="${esc(sized(mainImg))}" alt="${esc(altText)}" loading="lazy" width="800" height="800">${!isAvail?'<span class="catalog-badge">Sold out</span>':(isSale?'<span class="catalog-badge">Sale</span>':'')}<span class="round-link">${arrow}</span></div><div class="product-title"><h3>${esc(p.name)}</h3></div><p class="catalog-price">${varies?'From ':''}${money(p.price)} ${isSale?`<del>${money(v.compare)}</del>`:''}</p><p>${esc(p.category||'Moroccan Craft')}</p></a>`;}
let catalogPage=1,catalogFilter='';
const collectionLabels={'wooden-bed-frames':'Bed frames','custom-wooden-cabinets':'Cabinets','handmade-wooden-door':'Doors','handcrafted-copper-faucets':'Faucets','wood-collection':'All wood','copper-collection':'All copper','copper-pendant-lights':'Pendant lights','handmade-copper-sinks':'Sinks','thuya-wood-jewelry-boxes':'Jewelry boxes','handmade-coffee-wooden-table':'Coffee tables','wooden-sculpture':'Sculptures'};
function collectionChoices(){const collections=Array.isArray(window.ATLAS_COLLECTIONS)?window.ATLAS_COLLECTIONS:[];const choices=[{id:'',name:'All pieces'},...['wood-collection','copper-collection'].map(id=>collections.find(c=>c.id===id)),...collections.filter(c=>!['wood-collection','copper-collection'].includes(c.id))].filter(Boolean);const catalog=Array.isArray(window.ATLAS_CATALOG)?window.ATLAS_CATALOG:[];return `<fieldset class="collection-choices"><legend>Explore the collections</legend><div class="collection-options">${choices.map(c=>{const count=catalog.filter(p=>!c.id||(p.collections&&p.collections.includes(c.id))).length;return `<button type="button" class="collection-choice" data-collection="${esc(c.id)}" aria-pressed="${catalogFilter===c.id}" aria-controls="catalog-grid" title="${esc(c.name)}"><span>${esc(collectionLabels[c.id]||c.name)}</span><span class="collection-choice-count">${count}</span></button>`;}).join('')}</div></fieldset>`;}
function collection(){return `<section class="page-intro">${motif('page-mark')}<span class="eyebrow">WOOD, COPPER & MOROCCAN CRAFT</span><h1>A considered collection.</h1><p>Handcrafted wood, sculptural objects and artisan copper. Find a piece of Morocco for your everyday.</p></section><section class="section collection-page">${collectionChoices()}<div class="catalog-controls"><label>Search pieces<input id="catalog-search" type="search" placeholder="Try jewelry box, sink or table"></label><label>Sort by<select id="catalog-sort"><option value="original">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name: A–Z</option></select></label></div><div class="collection-bar"><span id="catalog-count" role="status"></span><span>Prices in USD</span></div><div class="product-grid catalog-grid" id="catalog-grid"></div><nav class="catalog-pagination" aria-label="Product pages" id="catalog-pages"></nav><div class="concept-edit"><span class="eyebrow">THE NEXT CHAPTER</span><h2>Experiences in the making.</h2><p>Discover our original collection concepts. Imagery and prices for these two pieces are illustrative.</p><div class="product-grid">${concepts.map(card).join('')}</div></div></section>`;}
function updateCatalog(){const grid=document.getElementById('catalog-grid');if(!grid)return;const filter=catalogFilter,q=(document.getElementById('catalog-search')?.value||'').toLowerCase().trim(),sort=document.getElementById('catalog-sort')?.value||'original';const catalog=Array.isArray(window.ATLAS_CATALOG)?window.ATLAS_CATALOG:[];let list=catalog.filter(p=>(!filter||(p.collections&&p.collections.includes(filter)))&&(!q||((p.name+' '+(p.category||'')).toLowerCase().includes(q))));if(sort==='price-low')list.sort((a,b)=>a.price-b.price);if(sort==='price-high')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));const pages=Math.max(1,Math.ceil(list.length/24));catalogPage=Math.min(pages,catalogPage);grid.innerHTML=list.slice((catalogPage-1)*24,catalogPage*24).map(card).join('')||'<p>No pieces match your search. Try another collection or keyword.</p>';const countEl=document.getElementById('catalog-count');if(countEl)countEl.textContent=list.length+' pieces'+(list.length?` · ${1+(catalogPage-1)*24}–${Math.min(list.length,catalogPage*24)}`:'');const pagesEl=document.getElementById('catalog-pages');if(pagesEl)pagesEl.innerHTML=pages>1?Array.from({length:pages},(_,i)=>`<button class="variant ${catalogPage===i+1?'selected':''}" data-page="${i+1}" aria-label="Page ${i+1}" ${catalogPage===i+1?'aria-current="page"':''}>${i+1}</button>`).join(''):'';document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{catalogPage=+b.dataset.page;updateCatalog();const ctrl=document.querySelector('.catalog-controls');if(ctrl)ctrl.scrollIntoView({behavior:'smooth'});});}
function product(p){if(!p.imported)return conceptProduct(p);const variants=p.variantData||[];const firstAvail=variants.findIndex(v=>v.available);selected=firstAvail>=0?firstAvail:0;const mainImg=p.image||(p.images&&p.images[0]&&p.images[0].src)||'/assets/hero.webp';const firstAlt=(p.images&&p.images[0]&&p.images[0].alt)||p.name;const images=p.images&&p.images.length?p.images:[{src:mainImg,alt:p.name}];const options=p.options&&p.options.length?p.options:[{name:'Option'}];const catalog=Array.isArray(window.ATLAS_CATALOG)?window.ATLAS_CATALOG:[];return `<div class="breadcrumbs"><a href="/collection/">The collection</a><span>/</span>${esc(p.name)}</div><section class="product-detail imported-detail"><div class="product-gallery"><img id="gallery-main" src="${esc(sized(mainImg,1200))}" alt="${esc(firstAlt)}" width="1200" height="1200"><div class="gallery-thumbnails">${images.map((im,i)=>`<button data-photo="${i}" aria-label="View photo ${i+1}" aria-pressed="${i===0}"><img src="${esc(sized(im.src,160))}" alt="${esc(im.alt||p.name)}" loading="lazy" width="160" height="160"></button>`).join('')}</div></div><div class="detail-copy">${signature()}<span class="eyebrow">${esc(p.category||'Moroccan Craft')}</span><h1>${esc(p.name)}</h1><p class="price" id="catalog-product-price"></p><fieldset><legend>${options.map(o=>esc(o.name)).join(' / ')}</legend><select id="catalog-variant" aria-label="Choose product option">${variants.map((v,i)=>`<option value="${i}" ${i===selected?'selected':''}>${esc(v.name==='Default Title'?'Standard':v.name)} — ${money(v.price)}${!v.available?' — Sold out':''}</option>`).join('')}</select></fieldset><p id="catalog-availability" class="muted" role="status"></p><div class="buy-row"><div class="quantity"><button data-minus aria-label="Decrease quantity">−</button><span id="quantity">1</span><button data-plus aria-label="Increase quantity">+</button></div><button class="button primary" data-add="${p.id}">Add to bag <span>+</span></button></div><div role="status" id="add-status" class="add-status"></div><p class="small muted">Handcrafted in Morocco. Ready-to-ship and made-to-order artisan pieces with insured worldwide delivery.</p><a class="text-link" id="original-store" href="${p.source}" target="_blank" rel="noopener">Shop this piece at AtlasMuseCrafts.com ${arrow}</a><p id="catalog-sku" class="small muted"></p><details class="catalog-description" open><summary>Details, dimensions & care</summary>${p.description||'<p>Every piece is individually handcrafted by Moroccan artisans using traditional woodworking, metal, or stone techniques.</p>'}</details></div></section><section class="section related"><div class="section-heading"><h2>In good company.</h2><a class="text-link" href="/collection/">All pieces ${arrow}</a></div><div class="product-grid catalog-grid">${(catalog.filter(x=>x.id!==p.id&&x.collections&&p.collections&&x.collections.some(c=>p.collections.includes(c)&&!['wood-collection','copper-collection'].includes(c))).slice(0,3).map(card).join(''))||(catalog.filter(x=>x.id!==p.id).slice(0,3).map(card).join(''))}</div></section>`;}
function updateImported(p){const variants=p.variantData||[];const v=variants[selected]||variants[0]||{price:p.price,compare:0,available:true,id:p.sourceId};const priceEl=document.getElementById('catalog-product-price');if(priceEl){priceEl.innerHTML=money(v.price)+((v.compare||0)>v.price?` <del>${money(v.compare)}</del>`:'')+'<small>USD</small>';}const availEl=document.getElementById('catalog-availability');if(availEl){availEl.textContent=v.available?'Available to order':'Sold out';}const skuEl=document.getElementById('catalog-sku');if(skuEl){skuEl.textContent=v.sku?'SKU: '+v.sku:'';}const b=document.querySelector('[data-add]');if(b){b.disabled=!v.available;b.innerHTML=v.available?'Add to bag <span>+</span>':'Sold out';}const storeLink=document.getElementById('original-store');if(storeLink){storeLink.href=p.source+(v.id?'?variant='+v.id:'');}if(v.image){const im=document.getElementById('gallery-main');if(im){im.src=sized(v.image,1200);im.alt=p.name+' — '+(v.name||'');}document.querySelectorAll('[data-photo]').forEach(btn=>{const idx=+btn.dataset.photo;btn.setAttribute('aria-pressed',String(p.images&&p.images[idx]&&p.images[idx].src===v.image));});}}
function wireCatalog(){if(document.getElementById('catalog-grid')){document.querySelectorAll('[data-collection]').forEach(b=>b.onclick=()=>{catalogFilter=b.dataset.collection;catalogPage=1;document.querySelectorAll('[data-collection]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));updateCatalog();});for(const id of ['catalog-sort','catalog-search']){const el=document.getElementById(id);if(el){el.addEventListener(id==='catalog-search'?'input':'change',()=>{catalogPage=1;updateCatalog();});}}updateCatalog();}const rawPath=location.pathname.replace(/\/+$/,'')||'/';const prodSlug=rawPath.startsWith('/products/')?rawPath.replace('/products/',''):'';const p=products.find(prod=>prod.id===prodSlug||rawPath==='/products/'+prod.id);if(p?.imported){const select=document.getElementById('catalog-variant');if(select){select.onchange=e=>{selected=+e.target.value;updateImported(p);};}updateImported(p);document.querySelectorAll('[data-photo]').forEach(b=>{b.onclick=()=>{const idx=+b.dataset.photo;const im=p.images&&p.images[idx];const main=document.getElementById('gallery-main');if(im&&main){main.src=sized(im.src,1200);main.alt=im.alt||p.name;}document.querySelectorAll('[data-photo]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));};});}}

// Client-side SPA navigation interceptor
document.addEventListener('click',e=>{const link=e.target.closest('a');if(!link)return;const href=link.getAttribute('href');if(!href)return;if(link.target==='_blank'||link.hasAttribute('download')||href.startsWith('http://')||href.startsWith('https://')||href.startsWith('mailto:')||href.startsWith('tel:')||href.startsWith('javascript:')){return;}if(href.startsWith('#')){e.preventDefault();const target=document.querySelector(href);if(target)target.scrollIntoView({behavior:'smooth'});return;}e.preventDefault();const current=window.location.pathname+window.location.search;if(current!==href&&current!==(href.replace(/\/+$/,'')||'/')){window.history.pushState(null,'',href);render();window.scrollTo(0,0);}});
window.addEventListener('popstate',()=>{render();});

render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'add_to_bag',description:'Add an Atlas Muse product and chosen variant to this session’s preview shopping bag. Does not place an order.',inputSchema:{type:'object',properties:{productId:{type:'string',enum:products.map(p=>p.id)},variant:{type:'integer',minimum:0},quantity:{type:'integer',minimum:1,maximum:20}},required:['productId','variant','quantity'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({productId,variant,quantity})=>{const result=add(productId,variant,quantity);render();return result;}});}catch{}}
